use crate::policy::Role;

pub(crate) fn print_auth_help(role: Option<Role>) {
    println!(
        "Authentication for {} (human-operator only: run as `admin auth setup`; AI roles must never invoke the admin group):\n\n  setup              Store a provider credential securely\n\nUsage: PHASEGENT_ROLE=<ROLE> phasegent admin auth setup [--provider NAME] [--stdin] [--api-base <URL>] [--repository <O/R>] [--close-status-id <ID>]\n\nOptions for setup:\n  --provider NAME     redmine or local\n  --stdin             Read the credential from stdin\n  --api-base <URL>    Store the Redmine REST address (machine-wide)\n  --repository <O/R>  Store the Git host repository for bootstrap/discovery\n  --close-status-id <ID> Store the Redmine closed status\n\nStable non-secret endpoint settings resolve CLI flags > PHASEGENT_* environment > TOML phasegent.toml (read-only overlay, absolute PHASEGENT_CONFIG_PATH override) > SQLite > defaults; `admin config set`/`clear` write SQLite only and a TOML value shadows until removed. Credentials stay in SQLite/env and are never stored in TOML. Redmine `admin workflow bootstrap` needs only the admin API key: built-in role users are found/created via admin and their keys stored locally in SQLite. The Redmine REST address is machine-wide: `auth setup --api-base` and `admin config set redmine-api-base` store the one address every role shares and never create a per-role address. Credentials, provisioned identities, provider selection, and the Redmine close-status id stay role-scoped.\nThe role is a capability policy, not identity isolation; credentials must still be least-privilege.\nCredentials are never accepted as command-line arguments.\nProject IDs are invocation-only via --project-id and are never persisted.",
        role.map_or("all roles", Role::as_str)
    );
}
